// OWNED BY v3-world (WP5a; world-art sign-off). The v3 world "Hollowmere" (the pixel3d town) as the game's tile world:
// `townLayoutV3` (the protocol TownLayout the server, voice and client rules use for `world: 'v3'` lobbies) and
// `townMapV3` (the v2-shaped render/ambience data: ground codes, objects, styles, lights, landmarks, plaza).
//
// The data is generated by scripts/v3/export-hollowmere.mjs from the read-only vendor copy v3/pixel3d
// (docs/v3/INTEGRATION.md §2.2/§2.3) into hollowmere.generated.json, committed next to this file. Never edit the
// JSON by hand: re-run the exporter (packages/assets/test/hollowmere.test.ts fails when the vendor copy or the exporter
// changed). The exporter's review data and freshness hashes live in hollowmere.meta.json (./meta.ts, tests and tools
// only), so a v3 client downloads only the runtime data below.
//
// Imported ONLY through the subpath '@ct/assets/hollowmere' (never from the package index): the client loads it as its
// own lazy chunk (apps/client/src/net/layout.ts), so a v2 lobby never downloads it. The server imports it statically.
import type { BuildingDef, TilePoint, TileRect, TownLayout } from '@ct/protocol';
import type { BuildingStyle, LightDef, MapObject, PropDef, TownMap } from '../layout.js';
import data from './hollowmere.generated.json';

/** Shape of hollowmere.generated.json (keys sorted by the exporter; the review data is in hollowmere.meta.json). */
export interface HollowmereJson {
  version: number;
  tileSize: number;
  widthTiles: number;
  heightTiles: number;
  townBounds: TileRect;
  /** heightTiles rows of widthTiles ground codes (v2 codes; interiors 'W' wall, 'f' floor, 'D' doorway). */
  ground: string[];
  /** heightTiles rows of widthTiles '0' / '1' (1 = blocked), row-major like TownLayout.collision. */
  collision: string[];
  /** house-0 .. house-14 (houseIndex = seat), then the enterable clock tower (houseIndex null, nobody's home). */
  buildings: BuildingDef[];
  /** The clock tower room's px <-> m translation (3D client): px = anchorPx + (m - anchorM) * tileSize. */
  towerRoom: { anchorPx: TilePoint; anchorM: { x: number; z: number } };
  circle: NonNullable<TownLayout['circle']>;
  square: TownLayout['square'];
  plaza: TownMap['plaza'];
  playerSpawn: TilePoint;
  storytellerSpawn: TilePoint;
  streetlights: TilePoint[];
  /** Townsfolk home tiles (TownScene's NPC list re-checked against this collision). */
  npcHomes: Record<string, TilePoint>;
  map: {
    objects: (MapObject & { walkable?: boolean })[];
    styles: Record<string, BuildingStyle>;
    decals: { x: number; y: number; name: string }[];
    lights: LightDef[];
    /** The vendor's outdoor prop kinds (2D sprite size, blocked rect relative to the anchor tile, walk-through flag). */
    propDefs: Record<string, PropDef & { walkable?: boolean }>;
  };
}

/** The raw exported data (tests, tools). */
export const hollowmere = data as unknown as HollowmereJson;

const H = hollowmere;

function expandCollision(rows: readonly string[], w: number, h: number): number[] {
  if (rows.length !== h) throw new Error(`hollowmere: ${rows.length} collision rows, expected ${h}`);
  const out = new Array<number>(w * h);
  rows.forEach((row, y) => {
    if (row.length !== w) throw new Error(`hollowmere: collision row ${y} has ${row.length} tiles, expected ${w}`);
    for (let x = 0; x < w; x++) out[y * w + x] = row.charCodeAt(x) === 49 ? 1 : 0;
  });
  return out;
}

const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

/**
 * The v3 world's TownLayout (version 3, 125 x 43 tiles: town 45 x 43 + five cottage band columns of stride 13 + a
 * sixth column for the clock tower's room). The clock tower is the 16th building: enterable, nobody's home.
 */
export const townLayoutV3: TownLayout = {
  version: H.version,
  widthTiles: H.widthTiles,
  heightTiles: H.heightTiles,
  tileSize: H.tileSize,
  townBounds: { ...H.townBounds },
  square: { ...H.square },
  buildings: clone(H.buildings),
  collision: expandCollision(H.collision, H.widthTiles, H.heightTiles),
  playerSpawn: { ...H.playerSpawn },
  storytellerSpawn: { ...H.storytellerSpawn },
  streetlights: H.streetlights.map((p) => ({ ...p })),
  circle: { ...H.circle },
};

/** The v3 world's render / ambience data in the v2 TownMap shape (Classic 2D in a v3 world, sound areas). */
export const townMapV3: TownMap = {
  width: H.widthTiles,
  height: H.heightTiles,
  tileSize: H.tileSize,
  ground: [...H.ground],
  objects: H.map.objects.map((o) => ({ ...o })),
  styles: clone(H.map.styles),
  lights: H.map.lights.map((l) => ({ ...l })),
  decals: H.map.decals.map((d) => ({ ...d })),
  landmarks: [], // the clock tower is an enterable building in this world (townLayoutV3.buildings)
  plaza: { ...H.plaza },
};

/** The clock tower room's px <-> m translation (bld:clocktower; the 3D room is the vendor's src/demo/tower-interior.js). */
export const towerRoomV3: Readonly<HollowmereJson['towerRoom']> = clone(H.towerRoom);

/** Townsfolk home tiles in the v3 world (TownScene / the 3D NPC roamer). */
export const npcHomesV3: Readonly<Record<string, TilePoint>> = clone(H.npcHomes);

/** Object kinds of the v3 world (the vendor's PROP_DEFS: some kinds differ from the v2 PROP_DEFS, e.g. flowerbarrel). */
export const PROP_DEFS_V3: Readonly<Record<string, PropDef & { walkable?: boolean }>> = clone(H.map.propDefs);
